export const KIND = {"id":72,"example":{"id":"E72","kind":72,"source":"aether","statement":["Write a class `vote::box` with the members `open()`, `cast()`, `close()` and `votes()`, safe to call from many threads at once.","A new box is closed and holds 0 votes.","`open()` opens it, `cast()` adds one vote, `close()` closes it, and `votes()` returns the number of votes.","Each throws `std::runtime_error`: `open()` when the box is open; `cast()` and `close()` when it is closed; and `votes()` when it is open.","Limits: none"],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <mutex>","#include <stdexcept>","","namespace vote {","","class box {","    int votes_ {0};","    bool open_ {false};","    std::mutex mutex_ {};","public:","    void open()","    {","        const std::lock_guard lock {mutex_};","        if (open_) {","            throw std::runtime_error {\"the box is open\"};","        }","        open_ = true;","    }","    void cast()","    {","        const std::lock_guard lock {mutex_};","        if (!open_) {","            throw std::runtime_error {\"the box is closed\"};","        }","        ++votes_;","    }","    void close()","    {","        const std::lock_guard lock {mutex_};","        if (!open_) {","            throw std::runtime_error {\"the box is closed\"};","        }","        open_ = false;","    }","    int votes()","    {","        const std::lock_guard lock {mutex_};","        if (open_) {","            throw std::runtime_error {\"the box is open\"};","        }","        return votes_;","    }","};","","}  // namespace vote"],"frame":[0,2,3,5,44,46],"labels":[{"at":7,"level":1,"text":"Write a class that keeps its data in private members."},{"at":10,"level":0,"text":"Hold a `std::mutex`, from `mutex`, which only one thread at a time can lock."},{"at":12,"level":1,"text":"Write member functions that lock the data, stop with an error when a test fails, else change it."},{"at":14,"level":2,"text":"Stop with an error when the box is open, else open it."},{"at":14,"level":0,"text":"Lock the mutex with `std::lock_guard`, which unlocks it when the function ends."},{"at":16,"level":0,"text":"Stop with a `std::runtime_error`, the error for a call that comes at the wrong time."},{"at":22,"level":2,"text":"Stop with an error when the box is closed, else add one vote."},{"at":30,"level":2,"text":"Stop with an error when the box is closed, else close it."},{"at":36,"level":1,"text":"Write a member function that locks the data, stops with an error when a test fails, else gives back the data."}],"blanks":[]}},"trace":{"id":"T72","lines":["#include <iostream>","#include <mutex>","#include <print>","","int main()","{","    std::mutex mutex {};","    int total {0};","    int number {0};","    while (std::cin >> number) {","        const std::lock_guard lock {mutex};","        if (number < 0) {","            break;","        }","        total += number;","    }","    std::println(\"{}\", total);","}"],"columns":["total","number"],"inputs":["4 -1 5\n","3 3 3\n"],"rows":[{"line":7,"values":["",""]},{"line":8,"values":["0",""]},{"line":9,"values":["0","0"]},{"line":10,"values":["0","4"]},{"line":11,"values":["0","4"]},{"line":12,"values":["0","4"]},{"line":15,"values":["4","4"]},{"line":10,"values":["4","-1"]},{"line":11,"values":["4","-1"]},{"line":12,"values":["4","-1"]},{"line":13,"values":["4","-1"]},{"line":17,"values":["4","-1"]}],"output":"9\n"},"traces":[],"problems":{"72.01":{"id":"72.01","kind":72,"source":"exercism","statement":["Write a class `Bankaccount::Bankaccount` with the members `open()`, `close()`, `deposit(int amount)`, `withdraw(int amount)` and `balance()`, safe to call from many threads at once.","A new object is closed.","`open()` opens it with a balance of 0, and `close()` closes it.","`deposit` adds amount to the balance, `withdraw` takes amount from it, and `balance()` returns it.","Each throws `std::runtime_error`: `open()` when the account is open; `close()`, `deposit`, `withdraw` and `balance()` when it is closed; `deposit` and `withdraw` when amount is below 0; and `withdraw` when amount is more than the balance.","Limits: none"],"examples":[{"input":"Newly opened account has zero balance","output":""}],"tests":[{"input":"Single deposit","output":""},{"input":"Multiple deposits","output":""},{"input":"Withdraw once","output":""},{"input":"Withdraw twice","output":""},{"input":"Can do multiple operations sequentially","output":""},{"input":"annot check balance of closed account","output":""},{"input":"Cannot deposit into closed account","output":""},{"input":"Cannot deposit into unopened account","output":""},{"input":"Cannot withdraw from closed account","output":""},{"input":"Cannot close an account that was not opened","output":""},{"input":"Cannot open an already opened account","output":""},{"input":"Reopened account does not retain balance","output":""},{"input":"Cannot withdraw more than deposited","output":""},{"input":"Cannot withdraw negative","output":""},{"input":"Cannot deposit negative","output":""},{"input":"Can handle concurrent transactions","output":""}],"solution":{"lines":["#pragma once","","#include <mutex>","#include <stdexcept>","","namespace Bankaccount {","","class Bankaccount {","    int balance_ {0};","    bool open_ {false};","    std::mutex mutex_ {};","public:","    void open()","    {","        const std::lock_guard lock {mutex_};","        if (open_) {","            throw std::runtime_error {\"the account is open\"};","        }","        open_ = true;","        balance_ = 0;","    }","    void close()","    {","        const std::lock_guard lock {mutex_};","        if (!open_) {","            throw std::runtime_error {\"the account is closed\"};","        }","        open_ = false;","    }","    void deposit(int amount)","    {","        const std::lock_guard lock {mutex_};","        if (!open_ || amount < 0) {","            throw std::runtime_error {\"cannot deposit\"};","        }","        balance_ += amount;","    }","    void withdraw(int amount)","    {","        const std::lock_guard lock {mutex_};","        if (!open_ || amount < 0 || amount > balance_) {","            throw std::runtime_error {\"cannot withdraw\"};","        }","        balance_ -= amount;","    }","    int balance()","    {","        const std::lock_guard lock {mutex_};","        if (!open_) {","            throw std::runtime_error {\"the account is closed\"};","        }","        return balance_;","    }","};","","}  // namespace Bankaccount"],"frame":[0,2,3,5,53,55],"labels":[{"at":7,"level":1,"text":"Write a class that keeps its data in private members."},{"at":12,"level":1,"text":"Write member functions that lock the data, stop with an error when a test fails, else change it."},{"at":14,"level":2,"text":"Stop with an error when the account is open, else open it with a balance of 0."},{"at":23,"level":2,"text":"Stop with an error when the account is closed, else close it."},{"at":31,"level":2,"text":"Stop with an error when the account is closed or the amount is below 0, else add it."},{"at":39,"level":2,"text":"Stop with an error when the account is closed or the amount is below 0 or above the balance, else take it away."},{"at":45,"level":1,"text":"Write a member function that locks the data, stops with an error when a test fails, else gives back the data."}],"blanks":[{"line":8,"from":17,"to":20},{"line":15,"from":12,"to":17},{"line":24,"from":12,"to":18},{"line":29,"from":17,"to":27},{"line":32,"from":22,"to":32},{"line":40,"from":36,"to":53},{"line":48,"from":12,"to":18}]},"fn":{"slug":"bank-account","commit":"8d139cb0","header":"bank_account.h","name":"bank_account_test.cpp","test":"#include \"bank_account.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n#include <chrono>\n#include <string>\n#include <thread>\n\nTEST_CASE(\"Newly opened account has zero balance\",\n          \"[983a1528-4ceb-45e5-8257-8ce01aceb5ed]\") {\n    Bankaccount::Bankaccount account{};\n    account.open();\n    REQUIRE(account.balance() == 0);\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"Single deposit\", \"[e88d4ec3-c6bf-4752-8e59-5046c44e3ba7]\") {\n    Bankaccount::Bankaccount account{};\n    account.open();\n    account.deposit(100);\n    REQUIRE(account.balance() == 100);\n}\n\nTEST_CASE(\"Multiple deposits\", \"[3d9147d4-63f4-4844-8d2b-1fee2e9a2a0d]\") {\n    Bankaccount::Bankaccount account{};\n    account.open();\n    account.deposit(100);\n    account.deposit(50);\n    REQUIRE(account.balance() == 150);\n}\n\nTEST_CASE(\"Withdraw once\", \"[08f1af07-27ae-4b38-aa19-770bde558064]\") {\n    Bankaccount::Bankaccount account{};\n    account.open();\n    account.deposit(100);\n    account.withdraw(75);\n    REQUIRE(account.balance() == 25);\n}\n\nTEST_CASE(\"Withdraw twice\", \"[6f6d242f-8c31-4ac6-8995-a90d42cad59f]\") {\n    Bankaccount::Bankaccount account{};\n    account.open();\n    account.deposit(100);\n    account.withdraw(80);\n    account.withdraw(20);\n    REQUIRE(account.balance() == 0);\n}\n\nTEST_CASE(\"Can do multiple operations sequentially\",\n          \"[45161c94-a094-4c77-9cec-998b70429bda]\") {\n    Bankaccount::Bankaccount account{};\n    account.open();\n    account.deposit(100);\n    account.deposit(110);\n    account.withdraw(200);\n    account.deposit(60);\n    account.withdraw(50);\n    REQUIRE(account.balance() == 20);\n}\n\nTEST_CASE(\"annot check balance of closed account\",\n          \"[f9facfaa-d824-486e-8381-48832c4bbffd]\") {\n    Bankaccount::Bankaccount account{};\n    account.open();\n    account.close();\n\n    REQUIRE_THROWS_AS(account.balance(), std::runtime_error);\n}\n\nTEST_CASE(\"Cannot deposit into closed account\",\n          \"[7a65ba52-e35c-4fd2-8159-bda2bde6e59c]\") {\n    Bankaccount::Bankaccount account{};\n    account.open();\n    account.close();\n\n    REQUIRE_THROWS_AS(account.deposit(50), std::runtime_error);\n}\n\nTEST_CASE(\"Cannot deposit into unopened account\",\n          \"[a0a1835d-faae-4ad4-a6f3-1fcc2121380b]\") {\n    Bankaccount::Bankaccount account{};\n    REQUIRE_THROWS_AS(account.deposit(50), std::runtime_error);\n}\n\nTEST_CASE(\"Cannot withdraw from closed account\",\n          \"[570dfaa5-0532-4c1f-a7d3-0f65c3265608]\") {\n    Bankaccount::Bankaccount account{};\n    account.open();\n    account.close();\n\n    REQUIRE_THROWS_AS(account.withdraw(50), std::runtime_error);\n}\n\nTEST_CASE(\"Cannot close an account that was not opened\",\n          \"[c396d233-1c49-4272-98dc-7f502dbb9470]\") {\n    Bankaccount::Bankaccount account;\n\n    REQUIRE_THROWS_AS(account.close(), std::runtime_error);\n}\n\nTEST_CASE(\"Cannot open an already opened account\",\n          \"[c06f534f-bdc2-4a02-a388-1063400684de]\") {\n    Bankaccount::Bankaccount account;\n    account.open();\n\n    REQUIRE_THROWS_AS(account.open(), std::runtime_error);\n}\n\nTEST_CASE(\"Reopened account does not retain balance\",\n          \"[0722d404-6116-4f92-ba3b-da7f88f1669c]\") {\n    Bankaccount::Bankaccount account;\n    account.open();\n    account.deposit(50);\n    account.close();\n    account.open();\n\n    REQUIRE(account.balance() == 0);\n}\n\nTEST_CASE(\"Cannot withdraw more than deposited\",\n          \"[ec42245f-9361-4341-8231-a22e8d19c52f]\") {\n    Bankaccount::Bankaccount account;\n    account.open();\n    account.deposit(25);\n\n    REQUIRE_THROWS_AS(account.withdraw(50), std::runtime_error);\n}\n\nTEST_CASE(\"Cannot withdraw negative\",\n          \"[4f381ef8-10ef-4507-8e1d-0631ecc8ee72]\") {\n    Bankaccount::Bankaccount account;\n    account.open();\n    account.deposit(100);\n    REQUIRE_THROWS_AS(account.withdraw(-50), std::runtime_error);\n}\n\nTEST_CASE(\"Cannot deposit negative\", \"[d45df9ea-1db0-47f3-b18c-d365db49d938]\") {\n    Bankaccount::Bankaccount account;\n    account.open();\n\n    REQUIRE_THROWS_AS(account.deposit(-50), std::runtime_error);\n}\n\nTEST_CASE(\"Can handle concurrent transactions\",\n          \"[ba0c1e0b-0f00-416f-8097-a7dfc97871ff]\") {\n    Bankaccount::Bankaccount account;\n    account.open();\n\n    std::vector<std::thread> vec_of_threads;\n\n    for (int i = 0; i < 1000; ++i) {\n        vec_of_threads.push_back(std::thread([&]() {\n            using namespace std::chrono_literals;\n            account.deposit(1);\n            std::this_thread::sleep_for(5ms);\n            account.withdraw(1);\n        }));\n    }\n\n    for (auto& th : vec_of_threads) {\n        th.join();\n    }\n\n    REQUIRE(account.balance() == 0);\n}\n#endif\n","setup":["Bankaccount::Bankaccount account{};","account.open();"],"calls":[{"call":"account.balance()","expected":"0"}]}},"72.02":{"id":"72.02","kind":72,"source":"aether","statement":["Write a class `turnstile::gate` with the members `unlock()`, `pass()` and `passes()`, safe to call from many threads at once.","A new gate is locked and has let 0 people through.","`unlock()` unlocks it; `pass()` lets one person through, adds one to the number of passes, and locks the gate again; `passes()` returns the number of passes.","Each throws `std::runtime_error`: `unlock()` when the gate is unlocked; `pass()` when it is locked; and `passes()` when it is unlocked.","Limits: none"],"examples":[{"input":"two_people_through","output":""}],"tests":[{"input":"new_gate_has_no_passes","output":""},{"input":"pass_a_locked_gate","output":""},{"input":"unlock_twice","output":""},{"input":"passes_while_unlocked","output":""},{"input":"pass_locks_again","output":""},{"input":"a_failed_pass_changes_nothing","output":""},{"input":"many_passes","output":""}],"solution":{"lines":["#pragma once","","#include <mutex>","#include <stdexcept>","","namespace turnstile {","","class gate {","    int passes_ {0};","    bool unlocked_ {false};","    std::mutex mutex_ {};","public:","    void unlock()","    {","        const std::lock_guard lock {mutex_};","        if (unlocked_) {","            throw std::runtime_error {\"the gate is unlocked\"};","        }","        unlocked_ = true;","    }","    void pass()","    {","        const std::lock_guard lock {mutex_};","        if (!unlocked_) {","            throw std::runtime_error {\"the gate is locked\"};","        }","        ++passes_;","        unlocked_ = false;","    }","    int passes()","    {","        const std::lock_guard lock {mutex_};","        if (unlocked_) {","            throw std::runtime_error {\"the gate is unlocked\"};","        }","        return passes_;","    }","};","","}  // namespace turnstile"],"frame":[0,2,3,5,37,39],"labels":[{"at":7,"level":1,"text":"Write a class that keeps its data in private members."},{"at":12,"level":1,"text":"Write member functions that lock the data, stop with an error when a test fails, else change it."},{"at":14,"level":2,"text":"Stop with an error when the gate is unlocked, else unlock it."},{"at":22,"level":2,"text":"Stop with an error when the gate is locked, else add one pass and lock it."},{"at":29,"level":1,"text":"Write a member function that locks the data, stops with an error when a test fails, else gives back the data."}],"blanks":[{"line":8,"from":16,"to":19},{"line":12,"from":4,"to":8},{"line":15,"from":12,"to":21},{"line":22,"from":36,"to":42},{"line":32,"from":12,"to":21}]},"fn":{"slug":"turnstile","commit":"","header":"turnstile.h","name":"turnstile_test.cpp","test":"#include \"turnstile.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"two_people_through\") {\n    turnstile::gate g {};\n    g.unlock();\n    g.pass();\n    g.unlock();\n    g.pass();\n    REQUIRE(g.passes() == 2);\n}\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"new_gate_has_no_passes\") {\n    turnstile::gate g {};\n    REQUIRE(g.passes() == 0);\n}\nTEST_CASE(\"pass_a_locked_gate\") {\n    turnstile::gate g {};\n    REQUIRE_THROWS_AS(g.pass(), std::runtime_error);\n}\nTEST_CASE(\"unlock_twice\") {\n    turnstile::gate g {};\n    g.unlock();\n    REQUIRE_THROWS_AS(g.unlock(), std::runtime_error);\n}\nTEST_CASE(\"passes_while_unlocked\") {\n    turnstile::gate g {};\n    g.unlock();\n    REQUIRE_THROWS_AS(g.passes(), std::runtime_error);\n}\nTEST_CASE(\"pass_locks_again\") {\n    turnstile::gate g {};\n    g.unlock();\n    g.pass();\n    REQUIRE_THROWS_AS(g.pass(), std::runtime_error);\n    REQUIRE(g.passes() == 1);\n}\nTEST_CASE(\"a_failed_pass_changes_nothing\") {\n    turnstile::gate g {};\n    REQUIRE_THROWS_AS(g.pass(), std::runtime_error);\n    REQUIRE(g.passes() == 0);\n}\nTEST_CASE(\"many_passes\") {\n    turnstile::gate g {};\n    for (int i {0}; i < 1000; ++i) {\n        g.unlock();\n        g.pass();\n    }\n    REQUIRE(g.passes() == 1000);\n}\n#endif\n","setup":["turnstile::gate g {};","g.unlock();","g.pass();","g.unlock();","g.pass();"],"calls":[{"call":"g.passes()","expected":"2"}]}}}}
